        /// <summary>
        ///   Looks up a localized string similar to I&apos;utente  {0}, non fa parte del ruolo {1}.
        /// </summary>
        internal static string UserNotInRole {
            get {
                return ResourceManager.GetString("UserNotInRole", resourceCulture);
            }
        }
    }
}
